import{_ as s,o as i,c as a,a0 as t}from"./chunks/framework.ZNB_GMSI.js";const k=JSON.parse('{"title":"Sign-in and entity commands","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/cli.md","filePath":"guide/deployment/cli.md"}'),n={name:"guide/deployment/cli.md"};function o(h,e,d,l,c,r){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="sign-in-and-entity-commands" tabindex="-1">Sign-in and entity commands <a class="header-anchor" href="#sign-in-and-entity-commands" aria-label="Permalink to &quot;Sign-in and entity commands&quot;">​</a></h1><p>The <code>authup</code> binary is also a client of a running deployment. <code>authup login</code> signs it in through the device authorization grant, and then one command per entity reads and manages records over the same typed client the consoles use.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><p>Create a public OAuth2 client (<code>authMethod: none</code>) in the realm the CLI users belong to and list the device grant on it: <code>grantTypes</code> must name <code>urn:ietf:params:oauth:grant-type:device_code</code>, and <code>refresh_token</code> keeps the sign-in alive past the access token&#39;s fifteen minutes. The grant is opt-in per client (see <a href="./../development/api-oauth2.html#_8-device-authorization-grant-rfc-8628">Device Authorization Grant</a>). There is deliberately no provisioned client for the CLI: the client&#39;s access policy is how an operator decides who may sign the CLI in, and a client authup provisioned into every realm would sit outside it.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">authup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://auth.example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --client</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --realm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span></span></code></pre></div><p><code>--client</code> takes the client&#39;s UUID, or its name together with <code>--realm</code> (a name repeats per realm; without a realm the master realm is assumed). Both are remembered per server, so a later <code>authup login</code> to the same server needs no flags. <code>--server</code> falls back to <code>AUTHUP_SERVER_URL</code>, then to the server of the last login. Plain <code>http:</code> is accepted for loopback only (<code>localhost</code>, <code>127.0.0.1</code>, <code>[::1]</code>).</p><p>The command prints the verification URL and the code; open the URL, sign in and confirm the code. The CLI polls until the approval lands.</p><h2 id="where-the-tokens-live" tabindex="-1">Where the tokens live <a class="header-anchor" href="#where-the-tokens-live" aria-label="Permalink to &quot;Where the tokens live&quot;">​</a></h2><p>The tokens go into the OS keychain: macOS Keychain, Windows Credential Manager, or Secret Service on Linux (GNOME Keyring, KWallet). A host with no keychain, an SSH session for instance, signs in with</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">authup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --insecure-storage</span></span></code></pre></div><p>which keeps the tokens in the hosts file instead, <code>0600</code>, next to the entry that names the client. The choice is recorded with the entry, so no later command needs the flag. A keychain that cannot be opened is an error; the CLI never falls back to the file on its own.</p><p>Everything else lives in <code>$XDG_CONFIG_HOME/authup/hosts.json</code> (default <code>~/.config/authup/hosts.json</code>): one entry per server with the client, the realm and the storage, plus which server is current.</p><h2 id="entity-commands" tabindex="-1">Entity commands <a class="header-anchor" href="#entity-commands" aria-label="Permalink to &quot;Entity commands&quot;">​</a></h2><p>Every entity the API serves is a command under <code>api</code>, named in kebab-case: <code>user</code>, <code>client</code>, <code>realm</code>, <code>role</code>, <code>permission</code>, <code>policy</code>, <code>scope</code>, <code>key</code>, <code>trust-anchor</code>, <code>session</code>, <code>session-token</code>, <code>event</code>, <code>consent</code>, <code>identity-provider</code>, <code>identity-provider-account</code>, <code>identity-provider-role-mapping</code>, <code>client-permission</code>, <code>client-role</code>, <code>client-scope</code>, <code>role-permission</code>, <code>user-role</code>, <code>user-permission</code>, <code>role-attribute</code>, <code>user-attribute</code>, <code>permission-policy</code>. Each carries the verbs its API has: <code>list</code>, <code>get &lt;id&gt;</code>, <code>create</code>, <code>update &lt;id&gt;</code>, <code>delete &lt;id&gt;</code>. A session cannot be created here and a <code>user-role</code> binding cannot be updated, because the API has no such call; <code>authup api &lt;entity&gt; --help</code> lists what exists. The group keeps the entity names, which follow the API, apart from the operator commands next to them.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">authup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;name=~ali~&amp;realm.name=master&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sort</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -createdAt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">authup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3f2a...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> realm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">authup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;:&quot;alice&quot;,&quot;realmId&quot;:&quot;...&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">authup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3f2a...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @alice.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">authup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3f2a...</span></span></code></pre></div><p><code>--filter</code>, <code>--sort</code>, <code>--fields</code> and <code>--include</code> take the values the <a href="./../development/api-query-language.html">API query language</a> documents, so a value carries its own operator: <code>name=alice</code> is exact, <code>name=ali~</code> starts with, <code>name=~ali</code> ends with and <code>name=~ali~</code> contains. Several filter conditions ride one <code>--filter</code>, joined by <code>&amp;</code>. <code>--data</code> holds a JSON object inline, <code>@&lt;path&gt;</code> reads a file, <code>@-</code> reads stdin. The response body is printed as JSON, so <code>authup api user list | jq &#39;.data[].name&#39;</code> composes. The signed-in user&#39;s permissions govern every call, as they do in the consoles.</p><h2 id="who-am-i-and-signing-out" tabindex="-1">Who am I, and signing out <a class="header-anchor" href="#who-am-i-and-signing-out" aria-label="Permalink to &quot;Who am I, and signing out&quot;">​</a></h2><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">authup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whoami</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">authup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logout</span></span></code></pre></div><p><code>whoami</code> names the signed-in user, the realm, the server, the client and where the tokens are kept. <code>logout</code> revokes the access and the refresh token and forgets the server. It does not end the browser session the approval came from: the device grant&#39;s tokens share that session, so ending it would sign the browser out too.</p><p>An access token that lapsed is renewed with the refresh token on the next command, and the rotated pair replaces the stored one. Two commands renewing at the same moment take a lock, so a refresh token is never presented twice.</p>`,20)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
